//! Native issued numeric-fact DATA adapter. The actual Source driver validates
//! SAME acquisition/lexer frame BEFORE lending its bytes/facts; span/radix alone
//! are never source identity or a current model/EOF grant.
use super::funded_storage::MacroText;
use dm_syntax::{OriginalNumberFacts,SettingAdmission};
use dm_syntax::numeric_form::{OriginalNumber,OriginalNumberNotice};
use std::io;
enum Notice{PrecisionLoss{value:f32},BadInteger{radix:u32,error:std::num::ParseIntError},BadFloat{error:std::num::ParseFloatError}}
pub(crate) struct IssuedNumber{normalized:MacroText,value:OriginalNumber,notice:Option<Notice>}
impl IssuedNumber{
 pub(crate) fn from_issued_facts_using(facts:&OriginalNumberFacts,actual_bytes:&[u8],a:&SettingAdmission<'_>)->io::Result<Self>{
  let mut normalized=MacroText::new(a)?;
  facts.visit_normalized(actual_bytes,|chunk|{let text=std::str::from_utf8(chunk).map_err(|_|io::Error::new(io::ErrorKind::InvalidData,"issued number normalizer emitted invalid UTF8"))?;normalized.push_str(text,a)})??;
  let actual=dm_syntax::numeric_form::original_number_value_using(normalized.as_str(),facts.integer(),facts.radix(),a)?;let value=actual.value;let notice=actual.notice.map(|notice|match notice{OriginalNumberNotice::PrecisionLoss{value,..}=>Notice::PrecisionLoss{value},OriginalNumberNotice::BadInteger{radix,error,..}=>Notice::BadInteger{radix,error},OriginalNumberNotice::BadFloat{error,..}=>Notice::BadFloat{error}});
  Ok(Self{normalized,value,notice})
 }
 pub(crate) fn value(&self)->OriginalNumber{self.value}
 pub(crate) fn normalized(&self)->&str{self.normalized.as_str()}
 pub(crate) fn write_notice_using(&self,out:&mut MacroText,a:&SettingAdmission<'_>)->io::Result<bool>{let Some(notice)=self.notice()else{return Ok(false)};super::funded_storage::formatted(out,a,|sink|notice.write_message(sink))?;Ok(true)}
 /// Borrow same already-parsed notice DATA; NEVER rerun the numeric parser.
 pub(crate) fn notice(&self)->Option<OriginalNumberNotice<'_>>{self.notice.as_ref().map(|notice|match notice{Notice::PrecisionLoss{value}=>OriginalNumberNotice::PrecisionLoss{buffer:self.normalized.as_str(),value:*value},Notice::BadInteger{radix,error}=>OriginalNumberNotice::BadInteger{buffer:self.normalized.as_str(),radix:*radix,error:error.clone()},Notice::BadFloat{error}=>OriginalNumberNotice::BadFloat{buffer:self.normalized.as_str(),error:error.clone()}})}
}
#[cfg(test)]mod tests{
 use super::*;use dm_syntax::{NativeTokenCursor,NativeTokenStep,NativeLexicalPurpose};use std::sync::{atomic::{Ordering}};
 fn facts(bytes:&[u8],a:&SettingAdmission<'_>)->OriginalNumberFacts{let mut cursor=NativeTokenCursor::for_purpose(NativeLexicalPurpose::Original0290Macro);assert!(matches!(cursor.peek_bytes_available_using(bytes,true,a,|_,_,_|panic!("following source diagnostic must remain undemanded")).unwrap(),NativeTokenStep::Token(_)));let facts=cursor.original_number_facts().unwrap().clone();cursor.commit_peek().unwrap();facts}
 #[test]fn same_actual_native_number_facts_keep_recovery_precision_and_exact_hash_byte_projection(){let used=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let a=SettingAdmission::new(&used,1<<20,&||Ok(()));let cases:Vec<&[u8]>=vec![b"08 \"unterminated",b"2147483648 \"unterminated",b"1e+-2+3",&[b'1',b'.',b'#',0xc3,0xa9],b"1.#INF trailing"];for bytes in cases{let issued=facts(bytes,&a);let number=IssuedNumber::from_issued_facts_using(&issued,bytes,&a).unwrap();if bytes.starts_with(b"08"){assert_eq!(number.value(),OriginalNumber::Integer(0));assert!(matches!(number.notice(),Some(OriginalNumberNotice::BadInteger{..})));}else if bytes.starts_with(b"2147"){assert_eq!(number.value(),OriginalNumber::Float(2147483648.0));let notice=number.notice().unwrap();assert!(notice.is_warning());let mut text=String::new();notice.write_message(&mut text).unwrap();assert_eq!(text,"precision loss of integer constant: \"2147483648\" to 2147483600");}else if bytes.starts_with(b"1e"){assert_eq!(number.normalized(),"1e+-2");assert!(matches!(number.notice(),Some(OriginalNumberNotice::BadFloat{..})));}else if bytes.get(3)==Some(&0xc3){assert_eq!(number.normalized(),"1.#Ã");assert!(matches!(number.notice(),Some(OriginalNumberNotice::BadFloat{..})));}else{assert!(matches!(number.value(),OriginalNumber::Float(n)if n==f32::INFINITY));assert!(number.notice().is_none());}drop(number);assert_eq!(used.load(Ordering::Acquire),dm_syntax::SettingChargeCounter::root_allocation_bytes());}}
 #[test]fn actual_normalized_buffer_denial_or_first_io_never_publishes_recovery_value_and_same_domain_recovers(){use std::cell::Cell;let used=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let healthy=SettingAdmission::new(&used,1<<20,&||Ok(()));let bytes=b"2147483648 rest";let actual=facts(bytes,&healthy);let tiny=SettingAdmission::new(&used,dm_syntax::SettingChargeCounter::root_allocation_bytes() + (3),&||Ok(()));assert_eq!(IssuedNumber::from_issued_facts_using(&actual,bytes,&tiny).err().unwrap().kind(),io::ErrorKind::OutOfMemory);assert_eq!(used.load(Ordering::Acquire),dm_syntax::SettingChargeCounter::root_allocation_bytes());let calls=Cell::new(0);let fault=||{calls.set(calls.get()+1);if calls.get()==4{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let failed=SettingAdmission::new(&used,1<<20,&fault);assert_eq!(IssuedNumber::from_issued_facts_using(&actual,bytes,&failed).err().unwrap().raw_os_error(),Some(1450));assert_eq!(used.load(Ordering::Acquire),dm_syntax::SettingChargeCounter::root_allocation_bytes());let recovered=IssuedNumber::from_issued_facts_using(&actual,bytes,&healthy).unwrap();assert!(recovered.notice().unwrap().is_warning());drop(recovered);assert_eq!(used.load(Ordering::Acquire),dm_syntax::SettingChargeCounter::root_allocation_bytes());}
 #[test]fn actual_number_notice_sink_preserves_first_io_and_same_normalized_value_for_retry(){let used=dm_syntax::SettingChargeCounter::try_new(dm_syntax::SettingChargeCounter::root_allocation_bytes()).unwrap();let a=SettingAdmission::new(&used,1<<20,&||Ok(()));let bytes=b"2147483648";let actual=facts(bytes,&a);let number=IssuedNumber::from_issued_facts_using(&actual,bytes,&a).unwrap();let mut out=MacroText::new(&a).unwrap();let before=used.load(Ordering::Acquire);let fault=||Err(io::Error::from_raw_os_error(1450));let failed=SettingAdmission::new(&used,1<<20,&fault);assert_eq!(number.write_notice_using(&mut out,&failed).unwrap_err().raw_os_error(),Some(1450));assert_eq!(used.load(Ordering::Acquire),before);assert_eq!(out.as_str(),"");assert_eq!(number.normalized(),"2147483648");assert!(number.write_notice_using(&mut out,&a).unwrap());assert_eq!(out.as_str(),"precision loss of integer constant: \"2147483648\" to 2147483600");drop((out,number));assert_eq!(used.load(Ordering::Acquire),dm_syntax::SettingChargeCounter::root_allocation_bytes());}

}
